# Regenerate the nanopb bindings for the C binding from spec/spec.proto.
#
# nanopb is pinned to 0.4.9.1: the checked-in `spec.pb.h` records the
# generator version in its first line ("Generated by nanopb-0.4.9.1"), and
# nanopb 1.0.0-dev writes a different marker and lays the file out
# differently, so an unpinned clone turns every regeneration into a whole-file
# rewrite. Bump the pin and the marker together.
NANOPB_VERSION=0.4.9.1

git clone --depth 1 --branch "$NANOPB_VERSION" https://github.com/nanopb/nanopb.git
cd nanopb
grep -v '^package' ../../spec/spec.proto > "spec.proto"
sed -i '' -e 's|string default |string default_ |g' spec.proto

python3 generator/nanopb_generator.py spec.proto

# Copy headers
cp pb_common.h ../../include/pb_common.h
cp pb_decode.h ../../include/pb_decode.h
cp pb_encode.h ../../include/pb_encode.h
cp pb.h ../../include/pb.h
cp spec.pb.h ../../include/spec.pb.h

# Copy impls
cp pb_common.c ../../lib/pb_common.c
cp pb_decode.c ../../lib/pb_decode.c
cp pb_encode.c ../../lib/pb_encode.c
cp spec.pb.c ../../lib/spec.pb.c

cd ..
rm -rf nanopb
